/**
 * A dependency compiled in full mode, the way an application is and a library
 * is not published. Its definitions are code for the runtime rather than data,
 * so a class that extends one has inputs the check cannot see.
 */
import { Directive, input } from '@angular/core';

/** FixtureCdkHeading's leak, in a definition the check cannot read. */
@Directive()
export abstract class FixtureFullHeading {
  readonly title = input('');
}
